fragment issue on Issue {number,title,url,createdAt,assignees(first:100){nodes{id,login,name,databaseId},totalCount},issueType{id,name,description,color},milestone{number,title,description,dueOn},updatedAt,state,closedAt}query IssueSearch($repo: String!, $owner: String!, $type: SearchType!, $limit: Int, $after: String, $query: String!) {
			repository(name: $repo, owner: $owner) {
				hasIssuesEnabled
			}
			search(type: $type, last: $limit, after: $after, query: $query) {
				issueCount
				nodes { ...issue }
				pageInfo {
					hasNextPage
					endCursor
				}
			}
		}

